using LUMAR_ERP_API_V2.DTOs.Settings;using LUMAR_ERP_API_V2.Services;using Microsoft.AspNetCore.Mvc;namespace LUMAR_ERP_API_V2.Controllers;
[ApiController][Route("settings")]public sealed class SettingsController(ISettingsService s):ControllerBase{[HttpGet]public async Task<ActionResult<IReadOnlyList<SystemSettingListDto>>> All(CancellationToken c)=>Ok(await s.GetAllAsync(c));[HttpGet("categories")]public async Task<ActionResult<IReadOnlyList<SettingCategoryDto>>> Categories(CancellationToken c)=>Ok(await s.GetCategoriesAsync(c));[HttpGet("categories/{category}")]public async Task<ActionResult<IReadOnlyList<SystemSettingListDto>>> Category(string category,CancellationToken c){if(string.IsNullOrWhiteSpace(category))return BadRequest("Category must not be empty.");return Ok(await s.GetByCategoryAsync(category,c));}[HttpGet("by-key/{key}")]public async Task<ActionResult<SystemSettingDetailsDto>> ByKey(string key,CancellationToken c){if(string.IsNullOrWhiteSpace(key))return BadRequest("Setting key must not be empty.");var x=await s.GetByKeyAsync(key,c);return x is null?NotFound():Ok(x);}[HttpGet("{id:int}")]public async Task<ActionResult<SystemSettingDetailsDto>> One(int id,CancellationToken c){if(id<=0)return BadRequest("Setting id must be positive.");var x=await s.GetByIdAsync(id,c);return x is null?NotFound():Ok(x);}[HttpPost][HttpPut("{id:int}")][HttpDelete("{id:int}")]public IActionResult Disabled()=>StatusCode(405,"Setting writes are disabled while LUMAR_ERP is read-only.");}